from decimal import Decimal, ROUND_HALF_UP, InvalidOperation


def vat_breakdown(lines: list[dict], mode: str) -> dict:
    if not isinstance(lines, list):
        raise ValueError('lines must be a list')
    if not isinstance(mode, str) or mode not in ('PER_LINE', 'PER_INVOICE'):
        raise ValueError('invalid mode')

    cents = Decimal('0.01')
    hundred = Decimal('100')
    allowed = {
        Decimal('0'): '0',
        Decimal('4'): '4',
        Decimal('10'): '10',
        Decimal('21'): '21',
    }

    parsed = []
    for line in lines:
        if not isinstance(line, dict):
            raise ValueError('line must be a dict')
        if 'quantity' not in line or 'unit_net' not in line or 'vat_rate' not in line:
            raise ValueError('line missing required keys')

        quantity = line['quantity']
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
            raise ValueError('invalid quantity')

        unit_raw = line['unit_net']
        if not isinstance(unit_raw, str):
            raise ValueError('invalid unit_net')
        try:
            unit_net = Decimal(unit_raw)
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid unit_net')
        if not unit_net.is_finite() or unit_net < 0:
            raise ValueError('invalid unit_net')
        if unit_net.as_tuple().exponent < -4:
            raise ValueError('invalid unit_net')

        rate_raw = line['vat_rate']
        if not isinstance(rate_raw, str):
            raise ValueError('invalid vat_rate')
        try:
            vat_rate = Decimal(rate_raw)
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid vat_rate')
        if not vat_rate.is_finite() or vat_rate not in allowed:
            raise ValueError('invalid vat_rate')
        canonical = allowed[vat_rate]

        parsed.append((quantity, unit_net, vat_rate, canonical))

    groups = {}
    if mode == 'PER_LINE':
        for quantity, unit_net, vat_rate, canonical in parsed:
            line_net = (Decimal(quantity) * unit_net).quantize(cents, rounding=ROUND_HALF_UP)
            line_vat = (line_net * vat_rate / hundred).quantize(cents, rounding=ROUND_HALF_UP)
            if canonical not in groups:
                groups[canonical] = [Decimal('0.00'), Decimal('0.00')]
            groups[canonical][0] += line_net
            groups[canonical][1] += line_vat
    else:
        exact_sums = {}
        rates_by_key = {}
        for quantity, unit_net, vat_rate, canonical in parsed:
            if canonical not in exact_sums:
                exact_sums[canonical] = Decimal('0')
                rates_by_key[canonical] = vat_rate
            exact_sums[canonical] += Decimal(quantity) * unit_net
        for canonical, exact_net in exact_sums.items():
            vat_rate = rates_by_key[canonical]
            group_net = exact_net.quantize(cents, rounding=ROUND_HALF_UP)
            group_vat = (group_net * vat_rate / hundred).quantize(cents, rounding=ROUND_HALF_UP)
            groups[canonical] = [group_net, group_vat]

    by_rate = {}
    total_net = Decimal('0.00')
    total_vat = Decimal('0.00')
    for canonical, values in groups.items():
        group_net = values[0].quantize(cents, rounding=ROUND_HALF_UP)
        group_vat = values[1].quantize(cents, rounding=ROUND_HALF_UP)
        group_gross = (group_net + group_vat).quantize(cents, rounding=ROUND_HALF_UP)
        by_rate[canonical] = {'net': group_net, 'vat': group_vat, 'gross': group_gross}
        total_net += group_net
        total_vat += group_vat

    total_net = total_net.quantize(cents, rounding=ROUND_HALF_UP)
    total_vat = total_vat.quantize(cents, rounding=ROUND_HALF_UP)
    total_gross = (total_net + total_vat).quantize(cents, rounding=ROUND_HALF_UP)
    return {'net': total_net, 'vat': total_vat, 'gross': total_gross, 'by_rate': by_rate}
